import Foundation

/// Maps the 24-bit OUI prefix of a MAC address to a short manufacturer name.
///
/// Backed by `oui.tsv` (generated by `scripts/generate-oui.sh`), one `PREFIX\tName` per line.
public final class VendorDatabase: Sendable {
    /// Lazily loaded on first access (Swift statics are initialized once, thread-safely).
    public static let shared: VendorDatabase = VendorDatabase(tsv: loadBundledTSV() ?? "")

    private let vendors: [UInt32: String]

    private static let resourceName = "oui"
    private static let resourceExtension = "tsv"

    public init(tsv: String) {
        var map: [UInt32: String] = [:]
        map.reserveCapacity(45_000)
        for line in tsv.utf8.split(separator: UInt8(ascii: "\n")) {
            guard let tab = line.firstIndex(of: UInt8(ascii: "\t")) else { continue }
            guard let key = Self.parsePrefix(line[line.startIndex..<tab]) else { continue }
            var nameBytes = line[line.index(after: tab)...]
            if nameBytes.last == UInt8(ascii: "\r") { nameBytes = nameBytes.dropLast() }
            guard !nameBytes.isEmpty, let name = String(bytes: nameBytes, encoding: .utf8) else { continue }
            map[key] = name
        }
        vendors = map
    }

    /// Number of known prefixes.
    public var count: Int { vendors.count }

    /// The vendor name, or nil for unknown prefixes and locally-administered (private/random) MACs.
    public func vendor(for mac: MACAddress) -> String? {
        guard !mac.isLocallyAdministered, mac.bytes.count >= 3 else { return nil }
        let key = UInt32(mac.bytes[0]) << 16 | UInt32(mac.bytes[1]) << 8 | UInt32(mac.bytes[2])
        return vendors[key]
    }

    private static func parsePrefix(_ bytes: some Collection<UInt8>) -> UInt32? {
        guard bytes.count == 6 else { return nil }
        var value: UInt32 = 0
        for b in bytes {
            let digit: UInt8
            switch b {
            case UInt8(ascii: "0")...UInt8(ascii: "9"): digit = b - UInt8(ascii: "0")
            case UInt8(ascii: "A")...UInt8(ascii: "F"): digit = b - UInt8(ascii: "A") + 10
            case UInt8(ascii: "a")...UInt8(ascii: "f"): digit = b - UInt8(ascii: "a") + 10
            default: return nil
            }
            value = value << 4 | UInt32(digit)
        }
        return value
    }

    /// `Bundle.main` first (the packaged app copies oui.tsv into Contents/Resources), then the
    /// SwiftPM resource bundle.
    private static func loadBundledTSV() -> String? {
        if let url = Bundle.main.url(forResource: resourceName, withExtension: resourceExtension),
            let text = try? String(contentsOf: url, encoding: .utf8)
        {
            return text
        }
        if let url = moduleBundleURL(), let text = try? String(contentsOf: url, encoding: .utf8) {
            return text
        }
        return nil
    }

    /// Looks up the SwiftPM resource bundle without touching `Bundle.module`'s accessor, which
    /// calls `fatalError` when the bundle is missing (e.g. a hand-assembled .app).
    private static func moduleBundleURL() -> URL? {
        let bundleName = "Lanternfish_LanternfishKit.bundle"
        var candidates: [URL] = []
        if let res = Bundle.main.resourceURL { candidates.append(res.appendingPathComponent(bundleName)) }
        candidates.append(Bundle.main.bundleURL.appendingPathComponent(bundleName))
        let selfBundle = Bundle(for: BundleToken.self)
        if let res = selfBundle.resourceURL { candidates.append(res.appendingPathComponent(bundleName)) }
        candidates.append(selfBundle.bundleURL.appendingPathComponent(bundleName))
        candidates.append(selfBundle.bundleURL.deletingLastPathComponent().appendingPathComponent(bundleName))
        for dir in candidates {
            if let bundle = Bundle(url: dir),
                let url = bundle.url(forResource: resourceName, withExtension: resourceExtension)
            {
                return url
            }
        }
        return nil
    }
}

private final class BundleToken {}
